function validate([gain]) {
  if (!Array.isArray(gain) || gain.length < 1 || gain.length > 100) return 'gain needs 1 to 100 values.';
  if (gain.some(v => !Number.isInteger(v) || v < -100 || v > 100)) return 'Each gain is an integer from -100 to 100.';
  return null;
}

