function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const span = size === 'large' || rand() < 0.3 ? 100 : 10;
  const bias = Math.floor(rand() * 3) - 1;
  const gain = Array.from({ length: n }, () => {
    const v = Math.floor(rand() * (2 * span + 1)) - span + bias * Math.floor(span / 4);
    return Math.max(-100, Math.min(100, v));
  });
  return [gain];
}
